<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref} from 'vue';
import type {Wire} from '../api';
import type {CaseProgress} from '../generated/CaseProgress';
import type {EvidenceSnapshot} from '../generated/EvidenceSnapshot';
import {addRelation,barRows,cellText,timelineRows,evidenceTitles} from '../evidence';
import {trapFocus} from '../accessibility';
import ResultTable from './ResultTable.vue';
const props=defineProps<{progress:Wire<CaseProgress>}>();
const emit=defineEmits<{change:[presentation:boolean],close:[],source:[id:string],rerun:[id:string],remove:[id:string]}>();
const board=computed(()=>props.progress.board);const dialog=ref<HTMLElement>();const viewport=ref<HTMLElement>();const closeButton=ref<HTMLButtonElement>();const from=ref('');const to=ref('');const relation=ref('explains');const message=ref('');
let drag:{id?:string,x:number,y:number,px:number,py:number,moved:boolean}|undefined;
const originalFocus=document.activeElement as HTMLElement|null;
onMounted(async()=>{await nextTick();closeButton.value?.focus();});onBeforeUnmount(()=>originalFocus?.focus());
function layout(card:Wire<EvidenceSnapshot>){return board.value.cards[card.id]??(board.value.cards[card.id]={x:30,y:30,view:'table',category:0,value:1});}
function begin(event:PointerEvent){if(event.button!==0)return;const target=event.target as Element;const handle=target.closest<HTMLElement>('[data-drag-card]');if(!handle&&target.closest('button,input,select,textarea,article'))return;const id=handle?.dataset.dragCard;const p=id?board.value.cards[id]:undefined;drag={id,x:event.clientX,y:event.clientY,px:p?.x??board.value.x,py:p?.y??board.value.y,moved:false};viewport.value?.setPointerCapture(event.pointerId);}
function move(event:PointerEvent){if(!drag)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;drag.moved ||= Math.abs(dx)+Math.abs(dy)>2;const p=drag.id?board.value.cards[drag.id]:undefined;if(p){p.x=Math.max(-10000,Math.min(10000,drag.px+dx/board.value.zoom));p.y=Math.max(-10000,Math.min(10000,drag.py+dy/board.value.zoom));}else{board.value.x=drag.px+dx;board.value.y=drag.py+dy;}}
function finish(){if(drag?.moved)emit('change',true);drag=undefined;}
function moveKey(event:KeyboardEvent,card:Wire<EvidenceSnapshot>){const delta=event.shiftKey?40:10;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const p=layout(card);p.x+=event.key==='ArrowLeft'?-delta:event.key==='ArrowRight'?delta:0;p.y+=event.key==='ArrowUp'?-delta:event.key==='ArrowDown'?delta:0;emit('change',true);}
function zoom(factor:number,event?:WheelEvent){const old=board.value.zoom;const value=Math.min(3,Math.max(.25,old*factor));if(event&&viewport.value){const bounds=viewport.value.getBoundingClientRect();const x=event.clientX-bounds.left,y=event.clientY-bounds.top;board.value.x=x-(x-board.value.x)*value/old;board.value.y=y-(y-board.value.y)*value/old;}board.value.zoom=value;emit('change',true);}
function arrange(){props.progress.evidence.forEach((card,i)=>Object.assign(layout(card),{x:30+i%3*350,y:30+Math.floor(i/3)*510}));board.value.x=0;board.value.y=0;board.value.zoom=.85;emit('change',true);}
function connect(){if(!props.progress.evidence.some(c=>c.id===from.value)||!props.progress.evidence.some(c=>c.id===to.value)||!addRelation(board.value,from.value,to.value,relation.value)){message.value='请选择不同的有效证据，避免重复关系。';return}message.value='关系已建立；结案清单将重新检查解释链。';emit('change',false);}
function label(id:string){const i=props.progress.evidence.findIndex(e=>e.id===id);return i<0?'已删除':`证据 ${i+1} · ${evidenceTitles[props.progress.evidence[i]!.task]??props.progress.evidence[i]!.task}`;}
const lines=computed(()=>board.value.relations.flatMap((r,i)=>{const a=board.value.cards[r.from],b=board.value.cards[r.to];if(!a||!b)return[];return[{...r,key:i,path:`M ${a.x+320} ${a.y+45} C ${a.x+365} ${a.y+45}, ${b.x-45} ${b.y+45}, ${b.x} ${b.y+45}`,x:(a.x+b.x+320)/2,y:(a.y+b.y)/2+32}];}));
function maxBar(card:Wire<EvidenceSnapshot>){const l=layout(card);return Math.max(1,...barRows(card.table,l.category,l.value).map(r=>Math.abs(r.value)));}
function onKey(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();emit('close');}else if(dialog.value)trapFocus(event,dialog.value);}
</script>
<template><section ref="dialog" class="evidence-workspace" role="dialog" aria-modal="true" aria-label="完整调查板" @keydown="onKey">
 <header class="board-header"><div><span class="eyebrow">INVESTIGATION BOARD</span><h2>让证据解释你的发现</h2></div><div class="toolbar"><span>{{progress.evidence.length}} / 20 张证据</span><button @click="zoom(1.2)">放大</button><button @click="zoom(1/1.2)">缩小</button><span>{{Math.round(board.zoom*100)}}%</span><button @click="arrange">自动整理</button><button ref="closeButton" data-testid="close-evidence-board" @click="emit('close')">返回调查 ×</button></div></header>
 <div class="board-link-tools"><label>来源<select v-model="from" data-testid="relation-source"><option value="">选择证据</option><option v-for="c in progress.evidence" :key="c.id" :value="c.id">{{label(c.id)}}</option></select></label><label>关系<select v-model="relation" data-testid="relation-kind"><option value="explains">由下一份证据解释</option><option value="related">普通关联</option></select></label><label>指向<select v-model="to" data-testid="relation-target"><option value="">选择证据</option><option v-for="c in progress.evidence.filter(e=>e.id!==from)" :key="c.id" :value="c.id">{{label(c.id)}}</option></select></label><button class="primary" data-testid="add-relation" @click="connect">建立关系</button><span role="status">{{message}}</span></div>
 <p class="board-instruction">拖动卡片标题或空白处移动画布；滚轮缩放。聚焦卡片标题后用方向键移动，Shift 加大步幅。结案需要：人数 → 请求 → 日志，日志再支持根因。</p>
 <div ref="viewport" class="board-viewport" @pointerdown="begin" @pointermove="move" @pointerup="finish" @pointercancel="finish" @wheel.prevent="zoom($event.deltaY<0?1.1:1/1.1,$event)"><div class="board-world" :style="{transform:`translate(${board.x}px,${board.y}px) scale(${board.zoom})`}">
 <svg class="board-lines" width="1" height="1" aria-label="证据之间的解释关系"><defs><marker id="evidence-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="var(--case-accent)"/></marker></defs><g v-for="line in lines" :key="line.key"><path :d="line.path" fill="none" :stroke="line.kind==='explains'?'var(--case-accent)':'var(--graph-edge)'" :stroke-width="line.kind==='explains'?3:2" :stroke-dasharray="line.kind==='related'?'6 5':undefined" marker-end="url(#evidence-arrow)"/><text :x="line.x" :y="line.y" text-anchor="middle" fill="var(--text)" font-size="12">{{line.kind==='explains'?'解释':'关联'}}</text></g></svg>
 <article v-for="(card,i) in progress.evidence" :key="card.id" class="board-card" :data-evidence="card.id" :data-task="card.task" :style="{left:`${layout(card).x}px`,top:`${layout(card).y}px`}"><button class="card-drag-handle" :data-drag-card="card.id" @keydown="moveKey($event,card)" title="拖动或使用方向键移动"><span>证据 {{String(i+1).padStart(2,'0')}}</span><strong>{{evidenceTitles[card.task]??card.task}}</strong><span aria-hidden="true">⠿</span></button><div class="board-card-content"><label>发现<input v-model="card.note" maxlength="4000" placeholder="给这份证据一个简短解释" @input="emit('change',false)"></label><small>{{card.snapshot}} · {{card.table.rows.length}} 行{{card.table.truncated?'（节选）':''}}</small><label>视图<select v-model="layout(card).view" @change="emit('change',true)"><option value="table">结果表格</option><option value="bar">柱状图</option><option value="timeline" :disabled="!card.table.columns.includes('event_seq')">事件时间线</option></select></label>
 <template v-if="layout(card).view==='bar'"><div class="chart-columns"><label>分类<select v-model.number="layout(card).category" @change="emit('change',true)"><option v-for="(column,n) in card.table.columns" :key="n" :value="n">{{column}}</option></select></label><label>数值<select v-model.number="layout(card).value" @change="emit('change',true)"><option v-for="(column,n) in card.table.columns" :key="n" :value="n">{{column}}</option></select></label></div><div class="evidence-bars" role="img" aria-label="证据柱状图"><div v-for="row in barRows(card.table,layout(card).category,layout(card).value)" :key="row.key"><span>{{row.label}}</span><i :style="{width:`${Math.abs(row.value)/maxBar(card)*100}%`}"/><b>{{row.text}}</b></div><p v-if="!barRows(card.table,layout(card).category,layout(card).value).length">所选列没有可绘制的数值。</p></div><small>前 20 条；图形近似，原始精确值见表格。</small></template>
 <ol v-else-if="layout(card).view==='timeline'" class="evidence-timeline"><li v-for="event in timelineRows(card.table).slice(0,20)" :key="event.index"><b>#{{event.sequence}}</b><span>{{event.row.map(cellText).join(' · ')}}</span></li></ol>
 <div v-else class="card-table-preview"><ResultTable :table="{...card.table,rows:card.table.rows.slice(0,6),truncated:card.table.truncated||card.table.rows.length>6}" compact/></div>
 <details><summary>原始类型化结果及 SQL</summary><pre>{{card.sql}}</pre><ResultTable :table="card.table" compact/></details><label v-if="card.task==='timeline'">日志支持的根因<select v-model="card.hypothesis" @change="emit('change',false)"><option value="">尚未关联</option><option value="stale_read">读取旧值后覆盖写入</option><option value="duplicate_name">身份混淆</option><option value="null_count">NULL 计数</option></select></label><div class="toolbar"><button @click="emit('source',card.id)">回到来源 SQL</button><button @click="emit('rerun',card.id)">重跑</button><button @click="emit('remove',card.id)">删除</button></div></div></article>
 </div><div v-if="!progress.evidence.length" class="empty large">先回到调查台，运行 SQL 并固定第一份发现。</div></div>
 <details class="board-relations"><summary>关系列表 · {{board.relations.length}}（可用键盘管理）</summary><div v-for="(r,i) in board.relations" :key="i"><span>{{label(r.from)}} → {{label(r.to)}} · {{r.kind==='explains'?'解释':'普通关联'}}</span><button @click="board.relations.splice(i,1);emit('change',false)">移除关系</button></div></details>
</section></template>
